let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"0fc8ec99ddef85c8\" body=\"loader() accepts different content sources based on a source interface.\">\n  `loader()` accepts different content sources based on a `source` interface.\n</FeedbackBlock>\n\nMultiple Sources [#multiple-sources]\n\n<FeedbackBlock id=\"a3d02c93805879fa\" body=\"Use multiple to combine multiple sources into one.\">\n  Use `multiple` to combine multiple sources into one.\n</FeedbackBlock>\n\n```ts\nimport { loader, multiple } from 'fumadocs-core/source';\nimport { openapiPlugin, openapiSource } from 'fumadocs-openapi/server';\nimport { blog, docs } from 'fumadocs-mdx:collections/server';\nimport { lucideIconsPlugin } from 'fumadocs-core/source/lucide-icons';\n\nexport const source = loader(\n  multiple({\n    docs: docs.toFumadocsSource(),\n    openapi: blog.toFumadocsSource(),\n  }),\n  {\n    baseUrl: '/docs',\n  },\n);\n```\n\n<FeedbackBlock id=\"d9c59647f6d895ec\" body=\"To access properties exclusive to each source:\">\n  To access properties exclusive to each source:\n</FeedbackBlock>\n\n```ts\nconst page = source.getPage(['...']);\n\nif (page.data.type === 'docs') {\n  console.log(page.data);\n} else {\n  console.log(page.data);\n}\n```\n\nCustom Source [#custom-source]\n\n<FeedbackBlock id=\"43e43baa8a965135\" body=\"To plug your own content source, create a Source object.\">\n  To plug your own content source, create a `Source` object.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"34c8a1dc8bc7e481\" body=\"Since Loader API doesn't rely on file system, file paths only allow virtual paths like file.mdx and content/file.mdx, ./file.mdx and D://content/file.mdx are not allowed.\">\n  Since Loader API doesn't rely on file system, file paths only allow virtual paths like `file.mdx` and `content/file.mdx`, `./file.mdx` and `D://content/file.mdx` are not allowed.\n</FeedbackBlock>\n\n```ts twoslash\nimport { Source } from 'fumadocs-core/source';\n\nexport function createMySource(): Source<{\n  metaData: { title: string; pages: string[] }; // Your custom type\n  pageData: { title: string; description?: string }; // Your custom type\n}> {\n  return {\n    files: [\n      {\n        type: 'page',\n        path: 'folder/index.mdx',\n        data: {\n          title: 'Hello World',\n          // ...\n        },\n      },\n      {\n        type: 'meta',\n        path: 'meta.json',\n        data: {\n          title: 'Docs',\n          pages: ['folder'],\n          // ...\n        },\n      },\n    ],\n  };\n}\n```\n";
